/*
 * uart_tx_scan.v -- Scan-inserted UART transmitter (manual, for TDF demo)
 *
 * This is a minimal scan-inserted wrapper around uart_tx for demonstrating
 * Transition Delay Fault (TDF) testing.  In production, this would be
 * generated by a DFT tool (Tessent, DFTMAX, Fault, etc.).
 *
 * Scan chain: 10 bits (simplified for demo)
 *   When se=1: FFs form a shift register (si -> ff0 -> ff1 -> ... -> so)
 *   When se=0: Normal functional mode
 */
module uart_tx_scan (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [7:0] tx_data,
    input  wire       tx_valid,
    output wire       tx_busy,
    output wire       tx_out,
    output wire       tx_done,
    // Scan ports
    input  wire       si,     // scan input
    input  wire       se,     // scan enable (1=shift, 0=functional)
    output wire       so      // scan output
);

    // Internal scan chain: 10 FFs
    reg [9:0] scan_reg;

    // Functional core (normal uart_tx)
    wire core_busy, core_tx, core_done;

    uart_tx core (
        .clk     (clk),
        .reset_n (rst_n),
        .data    (tx_data),
        .send    (tx_valid),
        .busy    (core_busy),
        .tx      (core_tx),
        .done    (core_done)
    );

    // Scan register: shift when se=1, hold when se=0
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            scan_reg <= 10'b0;
        end else if (se) begin
            scan_reg <= {si, scan_reg[9:1]};  // shift right, si into MSB
        end else begin
            // In functional mode, load some representation of core state
            // For demo: just hold previous value (simplified)
            scan_reg <= scan_reg;
        end
    end

    assign so = scan_reg[0];  // LSB is scan output

    // In functional mode, pass through core signals
    // (In real scan design, these would be muxed based on test mode)
    assign tx_busy = core_busy;
    assign tx_out  = core_tx;
    assign tx_done = core_done;

endmodule
